#include <stdio.h>
typedef struct { int id; int score; } Record;
int main(void) {
  Record records[3] = {{12, 80}, {7, 95}, {21, 88}};
  int best = 0;
  int total = 0;
  for (int i = 0; i < 3; i++) {
    total += records[i].score;
    if (records[i].score > records[best].score) best = i;
  }
  printf("total=%d,best_id=%d\n", total, records[best].id);
  return 0;
}

