typedef struct { int id; int score; } Record;
int main(void) {
  Record records[3];
  for (int i = 0; i < 3; i++) if (scanf("%d %d", &records[i].id, &records[i].score) != 2) return 1;
  int best = 0;
  for (int i = 1; i < 3; i++) if (records[i].score > records[best].score) best = i;
  printf("best_id=%d,best_score=%d\n", records[best].id, records[best].score);
  return 0;
}

