#include <stdio.h>
typedef struct { int code; int quantity; } Item;
int main(void) {
  Item items[4];
  int total = 0, first_empty = -1;
  for (int i = 0; i < 4; i++) {
    if (scanf("%d %d", &items[i].code, &items[i].quantity) != 2) return 1;
    total += items[i].quantity;
    if (items[i].quantity == 0 && first_empty == -1) first_empty = items[i].code;
  }
  printf("total=%d,first_empty=%d\n", total, first_empty);
  return 0;
}
